	'p_rows' => '[["Compte et demande", "pas de frais d\'ouverture, pas d\'abonnement, pas de volume minimal", "\\u20ac0"], ["Avance", "versée le jour ouvré suivant l\'approbation", "90 % de la facture"], ["Frais de financement, 30 premiers jours", "facturés une seule fois, annoncés avant votre accord", "1,4 % de la facture"], ["Chaque période suivante de 15 jours", "si votre client paie après 30 jours", "0,7 % de la facture"], ["Plafond des frais", "le maximum facturé pour une facture", "4,2 % de la facture"], ["Versement le jour même", "approbation avant 13 h 00 CET", "\\u20ac25 par facture"], ["Montant de la facture", "par facture, clients B2B dans l\'UE", "\\u20ac1 000\\u2013\\u20ac150 000"]]',
